<template><section class="section container" style="max-width:520px"><div class="eyebrow">Ruang redaksi</div><h1>Masuk ke dashboard</h1><form class="form" @submit.prevent="submit"><UiInput v-model="email" label="Email" type="email" required /><UiInput v-model="password" label="Password" type="password" required /><p v-if="error" style="color:#c5483e">{{ error }}</p><UiButton type="submit" icon="heroicons:arrow-right">Masuk</UiButton></form></section></template><script setup lang="ts">const auth=useAuthStore(); const toast=useToast(); const email=ref('admin@portalberita.test'); const password=ref('admin123'); const error=ref(''); async function submit(){try{await auth.login({email:email.value,password:password.value});toast.show('Berhasil masuk ke dashboard','success');navigateTo('/admin')}catch(e:any){error.value=e.response?.data?.message||'Login gagal';toast.show(error.value,'error')}} definePageMeta({layout:false})</script>
